import { ERRORS, required } from '../';

describe('required validator', () => {
  it('should fail validation on null', () => {
    expect(
      required({
        errors: [],
        value: null,
      }),
    ).toEqual([ERRORS.isRequired]);
  });

  it('should fail validation on false', () => {
    expect(
      required({
        errors: [],
        value: false,
      }),
    ).toEqual([ERRORS.isRequired]);
  });

  it('should fail validation on empty string', () => {
    expect(
      required({
        errors: [],
        value: '',
      }),
    ).toEqual([ERRORS.isRequired]);
  });

  it('should fail validation on empty arrays', () => {
    expect(
      required({
        errors: [],
        value: [],
      }),
    ).toEqual([ERRORS.isRequired]);
  });

  it('should not fail validation on abc', () => {
    expect(
      required({
        errors: [],
        value: 'abc',
      }),
    ).toEqual([]);
  });
});
